set term ^;
execute block as
declare i int = 1;
declare kk int;
begin
  -- ta: 300 rows, k = 0..59 (NULL for every 11th row), k2 = 0..6 (NULL for every 17th row)
  while (i <= 300) do
  begin
    kk = iif(mod(i, 11) = 0, null, mod(i, 60));
    insert into ta values (:i, :kk, iif(mod(:i, 17) = 0, null, mod(:i, 7)), mod(:i, 10),
      'v' || :kk, 'Ab' || :kk, dateadd(:kk day to date '2026-01-01'));
    i = i + 1;
  end
  -- tb: 300 rows, k = 10..74 (NULL for every 13th row): 0..9 of ta and 60..74 of tb have no pair
  i = 1;
  while (i <= 300) do
  begin
    kk = iif(mod(i, 13) = 0, null, mod(i, 65) + 10);
    insert into tb values (:i, :kk, iif(mod(:i, 19) = 0, null, mod(:i, 7)), mod(:i, 100),
      :kk, :kk + iif(mod(:i, 5) = 0, 0.50, 0), 'v' || :kk, 'aB' || :kk,
      dateadd(iif(mod(:i, 4) = 0, 12, 0) hour to dateadd(:kk day to timestamp '2026-01-01 00:00:00')),
      rpad('m' || :i || ';', 20 + mod(:i, 7) * 300, 'memo text '));
    insert into tbi values (:i, :kk, iif(mod(:i, 19) = 0, null, mod(:i, 7)), mod(:i, 100));
    i = i + 1;
  end
  -- tc: 100 rows, k = 20..49 (NULL for every 7th row)
  i = 1;
  while (i <= 100) do
  begin
    insert into tc values (:i, iif(mod(:i, 7) = 0, null, mod(:i, 30) + 20), mod(:i, 5));
    i = i + 1;
  end
  i = 0;
  while (i < 10) do
  begin
    insert into tt values (:i, :i * 10);
    i = i + 1;
  end
  i = 1;
  while (i <= 300) do
  begin
    insert into tu values (:i, :i);
    insert into tup values (:i, :i);
    i = i + 1;
  end
  -- tw: 30 rows, the record is longer than 64 KB
  i = 1;
  while (i <= 30) do
  begin
    insert into tw values (:i, 10 + :i, rpad('a' || :i, 100 + :i, 'x'), rpad('b', 32000, 'y'));
    i = i + 1;
  end
end^
