create view v_a as select id, k, k2, z from ta;
create view v_b as select id, k, k2, y from tb;
create view v_ab as
  select a.id as aid, a.k as ak, a.z, b.id as bid, b.y
  from ta a left join tb b on a.k = b.k and b.y > a.z * 10;
create view v_ab_n as
  select a.id as aid, a.k as ak, a.z, b.id as bid, b.y
  from ta a left join tb b on (a.k >= b.k and a.k <= b.k) and b.y > a.z * 10;
commit;

set term ^;
create procedure sp_a returns (id int, k int, k2 int, z int) as
begin
  for select id, k, k2, z from ta into :id, :k, :k2, :z do suspend;
end^
create procedure sp_b returns (id int, k int, k2 int, y int) as
begin
  for select id, k, k2, y from tb into :id, :k, :k2, :y do suspend;
end^
set term ;^
