-- ===== C: parent query references =====

-- C01: parent reference in ON (lateral derived table)
select 'C01 H' as tag, q.c, q.m, q.s
  from (select sum(x.c1) as c, sum(x.m1) as m, sum(x.s1 + p.k) as s
    from tt p cross join lateral (select count(*) as c1, count(b.id) as m1, coalesce(sum(a.id * 1000003 + coalesce(b.id, 0) * 1009), 0) as s1 from ta a left join tb b on a.k = b.k and b.y - a.z > p.v) x) q;
select 'C01' as tag, iif(h.c = n.c and h.m = n.m and h.s = n.s, 'PASS', 'FAIL') as res,
       h.c, h.m, h.s, n.c as nl_c, n.m as nl_m, n.s as nl_s
  from (select sum(x.c1) as c, sum(x.m1) as m, sum(x.s1 + p.k) as s
    from tt p cross join lateral (select count(*) as c1, count(b.id) as m1, coalesce(sum(a.id * 1000003 + coalesce(b.id, 0) * 1009), 0) as s1 from ta a left join tb b on a.k = b.k and b.y - a.z > p.v) x) h
  cross join (select sum(x.c1) as c, sum(x.m1) as m, sum(x.s1 + p.k) as s
    from tt p cross join lateral (select count(*) as c1, count(b.id) as m1, coalesce(sum(a.id * 1000003 + coalesce(b.id, 0) * 1009), 0) as s1 from ta a left join tb b on (a.k >= b.k and a.k <= b.k) and b.y - a.z > p.v) x) n;

-- C02: parent reference in ON (scalar sub-query, W1)
select 'C02 H' as tag, q.c, q.m, q.s
  from (select count(*) as c, sum(q.c1) as m, sum(q.c1 * (q.k + 1)) as s
    from (select p.k, (select count(b.id) from ta a left join tb b on a.k = b.k and b.y - a.z > p.v) as c1 from tt p) q) q;
select 'C02' as tag, iif(h.c = n.c and h.m = n.m and h.s = n.s, 'PASS', 'FAIL') as res,
       h.c, h.m, h.s, n.c as nl_c, n.m as nl_m, n.s as nl_s
  from (select count(*) as c, sum(q.c1) as m, sum(q.c1 * (q.k + 1)) as s
    from (select p.k, (select count(b.id) from ta a left join tb b on a.k = b.k and b.y - a.z > p.v) as c1 from tt p) q) h
  cross join (select count(*) as c, sum(q.c1) as m, sum(q.c1 * (q.k + 1)) as s
    from (select p.k, (select count(b.id) from ta a left join tb b on (a.k >= b.k and a.k <= b.k) and b.y - a.z > p.v) as c1 from tt p) q) n;

