    from tt p cross join lateral (select count(*) as c1, count(b.id) as m1, coalesce(sum(a.id * 1000003 + coalesce(b.id, 0) * 1009), 0) as s1 from ta a left join tb b on a.k = b.k and b.k2 = p.k) x) q;
select 'C03' as tag, iif(h.c = n.c and h.m = n.m and h.s = n.s, 'PASS', 'FAIL') as res,
