  from (select sum(x.c1) as c, sum(x.m1) as m, sum(x.s1 + p.k) as s
    from tt p cross join lateral (select count(*) as c1, count(b.id) as m1, coalesce(sum(a.id * 1000003 + coalesce(b.id, 0) * 1009), 0) as s1 from ta a left join tb b on a.k = b.k and b.k2 is not distinct from nullif(p.k, 3)) x) q;
select 'C08' as tag, iif(h.c = n.c and h.m = n.m and h.s = n.s, 'PASS', 'FAIL') as res,
       h.c, h.m, h.s, n.c as nl_c, n.m as nl_m, n.s as nl_s
  from (select sum(x.c1) as c, sum(x.m1) as m, sum(x.s1 + p.k) as s
    from tt p cross join lateral (select count(*) as c1, count(b.id) as m1, coalesce(sum(a.id * 1000003 + coalesce(b.id, 0) * 1009), 0) as s1 from ta a left join tb b on a.k = b.k and b.k2 is not distinct from nullif(p.k, 3)) x) h
  cross join (select sum(x.c1) as c, sum(x.m1) as m, sum(x.s1 + p.k) as s
    from tt p cross join lateral (select count(*) as c1, count(b.id) as m1, coalesce(sum(a.id * 1000003 + coalesce(b.id, 0) * 1009), 0) as s1 from ta a left join tb b on (a.k >= b.k and a.k <= b.k) and ((b.k2 >= nullif(p.k, 3) and b.k2 <= nullif(p.k, 3)) or (b.k2 is null and nullif(p.k, 3) is null))) x) n;

-- C09: lateral: ON refers to the parent table, the parent has an index for the join back (X1)
