  from (select count(*) as c, count(x.bid) as m, coalesce(sum(coalesce(p.id, 0) * 1000003 + coalesce(x.bid, 0) * 1009 + coalesce(0, 0)), 0) as s
    from tup p cross join lateral (select a.id, b.id as bid from ta a left join tb b on a.k = b.k and b.y > p.k) x where p.id = x.id) q;
select 'C09' as tag, iif(h.c = n.c and h.m = n.m and h.s = n.s, 'PASS', 'FAIL') as res,
       h.c, h.m, h.s, n.c as nl_c, n.m as nl_m, n.s as nl_s
  from (select count(*) as c, count(x.bid) as m, coalesce(sum(coalesce(p.id, 0) * 1000003 + coalesce(x.bid, 0) * 1009 + coalesce(0, 0)), 0) as s
    from tup p cross join lateral (select a.id, b.id as bid from ta a left join tb b on a.k = b.k and b.y > p.k) x where p.id = x.id) h
  cross join (select count(*) as c, count(x.bid) as m, coalesce(sum(coalesce(p.id, 0) * 1000003 + coalesce(x.bid, 0) * 1009 + coalesce(0, 0)), 0) as s
    from tup p cross join lateral (select a.id, b.id as bid from ta a left join tb b on (a.k >= b.k and a.k <= b.k) and b.y > p.k) x where p.id = x.id) n;

