    from tup p cross join lateral (select a.id, b.id as bid from ta a left join tb b on a.k = b.k and a.z < mod(p.k, 7)) x where p.id = x.id) h
  cross join (select count(*) as c, count(x.bid) as m, coalesce(sum(coalesce(p.id, 0) * 1000003 + coalesce(x.bid, 0) * 1009 + coalesce(0, 0)), 0) as s
    from tup p cross join lateral (select a.id, b.id as bid from ta a left join tb b on (a.k >= b.k and a.k <= b.k) and a.z < mod(p.k, 7)) x where p.id = x.id) n;

