-- F11: derived table with an outer join, joined inner
select 'F11 H' as tag, q.c, q.m, q.s
  from (select count(*) as c, count(a.bid) as m, coalesce(sum(coalesce(a.id, 0) * 1000003 + coalesce(a.bid, 0) * 1009 + coalesce(c.id, 0)), 0) as s
    from (select a.id, a.k, b.id as bid, b.y from ta a left join tb b on a.k = b.k) a join tc c on c.k = a.k and c.w * 20 < coalesce(a.y, 100)) q;
select 'F11' as tag, iif(h.c = n.c and h.m = n.m and h.s = n.s, 'PASS', 'FAIL') as res,
       h.c, h.m, h.s, n.c as nl_c, n.m as nl_m, n.s as nl_s
  from (select count(*) as c, count(a.bid) as m, coalesce(sum(coalesce(a.id, 0) * 1000003 + coalesce(a.bid, 0) * 1009 + coalesce(c.id, 0)), 0) as s
    from (select a.id, a.k, b.id as bid, b.y from ta a left join tb b on a.k = b.k) a join tc c on c.k = a.k and c.w * 20 < coalesce(a.y, 100)) h
  cross join (select count(*) as c, count(a.bid) as m, coalesce(sum(coalesce(a.id, 0) * 1000003 + coalesce(a.bid, 0) * 1009 + coalesce(c.id, 0)), 0) as s
    from (select a.id, a.k, b.id as bid, b.y from ta a left join tb b on (a.k >= b.k and a.k <= b.k)) a join tc c on (c.k >= a.k and c.k <= a.k) and c.w * 20 < coalesce(a.y, 100)) n;

-- F12: two outer joins to the same table
select 'F12 H' as tag, q.c, q.m, q.s
  from (select count(*) as c, count(b.id) as m, coalesce(sum(coalesce(a.id, 0) * 1000003 + coalesce(b.id, 0) * 1009 + coalesce(b2.id, 0)), 0) as s
    from ta a left join tb b on a.k = b.k and b.y < 50 left join tb b2 on a.k = b2.k and b2.y >= 50) q;
select 'F12' as tag, iif(h.c = n.c and h.m = n.m and h.s = n.s, 'PASS', 'FAIL') as res,
       h.c, h.m, h.s, n.c as nl_c, n.m as nl_m, n.s as nl_s
  from (select count(*) as c, count(b.id) as m, coalesce(sum(coalesce(a.id, 0) * 1000003 + coalesce(b.id, 0) * 1009 + coalesce(b2.id, 0)), 0) as s
    from ta a left join tb b on a.k = b.k and b.y < 50 left join tb b2 on a.k = b2.k and b2.y >= 50) h
  cross join (select count(*) as c, count(b.id) as m, coalesce(sum(coalesce(a.id, 0) * 1000003 + coalesce(b.id, 0) * 1009 + coalesce(b2.id, 0)), 0) as s
    from ta a left join tb b on (a.k >= b.k and a.k <= b.k) and b.y < 50 left join tb b2 on (a.k >= b2.k and a.k <= b2.k) and b2.y >= 50) n;

-- F13: inner join, then outer join with ON over the inner join partner
select 'F13 H' as tag, q.c, q.m, q.s
  from (select count(*) as c, count(b.id) as m, coalesce(sum(coalesce(a.id, 0) * 1000003 + coalesce(b.id, 0) * 1009 + coalesce(t.k, 0)), 0) as s
    from ta a join tt t on t.k = a.z left join tb b on b.k = a.k and b.y > t.v) q;
select 'F13' as tag, iif(h.c = n.c and h.m = n.m and h.s = n.s, 'PASS', 'FAIL') as res,
       h.c, h.m, h.s, n.c as nl_c, n.m as nl_m, n.s as nl_s
  from (select count(*) as c, count(b.id) as m, coalesce(sum(coalesce(a.id, 0) * 1000003 + coalesce(b.id, 0) * 1009 + coalesce(t.k, 0)), 0) as s
    from ta a join tt t on t.k = a.z left join tb b on b.k = a.k and b.y > t.v) h
  cross join (select count(*) as c, count(b.id) as m, coalesce(sum(coalesce(a.id, 0) * 1000003 + coalesce(b.id, 0) * 1009 + coalesce(t.k, 0)), 0) as s
    from ta a join tt t on (t.k >= a.z and t.k <= a.z) left join tb b on (b.k >= a.k and b.k <= a.k) and b.y > t.v) n;

-- F14: chain with an anti-join in the middle
select 'F14 H' as tag, q.c, q.m, q.s
  from (select count(*) as c, count(b.id) as m, coalesce(sum(coalesce(a.id, 0) * 1000003 + coalesce(b.id, 0) * 1009 + coalesce(c.id, 0)), 0) as s
    from ta a left join tb b on a.k = b.k left join tc c on c.k = a.k where b.id is null) q;
select 'F14' as tag, iif(h.c = n.c and h.m = n.m and h.s = n.s, 'PASS', 'FAIL') as res,
       h.c, h.m, h.s, n.c as nl_c, n.m as nl_m, n.s as nl_s
  from (select count(*) as c, count(b.id) as m, coalesce(sum(coalesce(a.id, 0) * 1000003 + coalesce(b.id, 0) * 1009 + coalesce(c.id, 0)), 0) as s
    from ta a left join tb b on a.k = b.k left join tc c on c.k = a.k where b.id is null) h
  cross join (select count(*) as c, count(b.id) as m, coalesce(sum(coalesce(a.id, 0) * 1000003 + coalesce(b.id, 0) * 1009 + coalesce(c.id, 0)), 0) as s
    from ta a left join tb b on (a.k >= b.k and a.k <= b.k) left join tc c on (c.k >= a.k and c.k <= a.k) where b.id is null) n;

-- F15: chain, anti-join at the end, conversion in the middle
select 'F15 H' as tag, q.c, q.m, q.s
  from (select count(*) as c, count(b.id) as m, coalesce(sum(coalesce(a.id, 0) * 1000003 + coalesce(b.id, 0) * 1009 + coalesce(c.id, 0)), 0) as s
    from ta a left join tb b on a.k = b.k left join tc c on c.k = a.k where c.id is null and b.id is not null) q;
select 'F15' as tag, iif(h.c = n.c and h.m = n.m and h.s = n.s, 'PASS', 'FAIL') as res,
       h.c, h.m, h.s, n.c as nl_c, n.m as nl_m, n.s as nl_s
  from (select count(*) as c, count(b.id) as m, coalesce(sum(coalesce(a.id, 0) * 1000003 + coalesce(b.id, 0) * 1009 + coalesce(c.id, 0)), 0) as s
    from ta a left join tb b on a.k = b.k left join tc c on c.k = a.k where c.id is null and b.id is not null) h
  cross join (select count(*) as c, count(b.id) as m, coalesce(sum(coalesce(a.id, 0) * 1000003 + coalesce(b.id, 0) * 1009 + coalesce(c.id, 0)), 0) as s
    from ta a left join tb b on (a.k >= b.k and a.k <= b.k) left join tc c on (c.k >= a.k and c.k <= a.k) where c.id is null and b.id is not null) n;

-- F16: chain, INDF key and a sub-query over three tables
select 'F16 H' as tag, q.c, q.m, q.s
  from (select count(*) as c, count(b.id) as m, coalesce(sum(coalesce(a.id, 0) * 1000003 + coalesce(b.id, 0) * 1009 + coalesce(c.id, 0)), 0) as s
    from ta a left join tb b on a.k = b.k left join tc c on c.w is not distinct from b.k2 and exists (select 1 from tt t where t.k = a.z and t.v < c.k + coalesce(b.y, 0))) q;
select 'F16' as tag, iif(h.c = n.c and h.m = n.m and h.s = n.s, 'PASS', 'FAIL') as res,
       h.c, h.m, h.s, n.c as nl_c, n.m as nl_m, n.s as nl_s
  from (select count(*) as c, count(b.id) as m, coalesce(sum(coalesce(a.id, 0) * 1000003 + coalesce(b.id, 0) * 1009 + coalesce(c.id, 0)), 0) as s
    from ta a left join tb b on a.k = b.k left join tc c on c.w is not distinct from b.k2 and exists (select 1 from tt t where t.k = a.z and t.v < c.k + coalesce(b.y, 0))) h
  cross join (select count(*) as c, count(b.id) as m, coalesce(sum(coalesce(a.id, 0) * 1000003 + coalesce(b.id, 0) * 1009 + coalesce(c.id, 0)), 0) as s
    from ta a left join tb b on (a.k >= b.k and a.k <= b.k) left join tc c on ((c.w >= b.k2 and c.w <= b.k2) or (c.w is null and b.k2 is null)) and exists (select 1 from tt t where t.k = a.z and t.v < c.k + coalesce(b.y, 0))) n;

-- F17: outer join whose outer side is an anti-join result
select 'F17 H' as tag, q.c, q.m, q.s
  from (select count(*) as c, count(b.id) as m, coalesce(sum(coalesce(a.id, 0) * 1000003 + coalesce(b.id, 0) * 1009 + coalesce(0, 0)), 0) as s
    from (select a.id, a.k from ta a left join tc c on c.k = a.k where c.id is null) a left join tb b on a.k = b.k) q;
select 'F17' as tag, iif(h.c = n.c and h.m = n.m and h.s = n.s, 'PASS', 'FAIL') as res,
       h.c, h.m, h.s, n.c as nl_c, n.m as nl_m, n.s as nl_s
  from (select count(*) as c, count(b.id) as m, coalesce(sum(coalesce(a.id, 0) * 1000003 + coalesce(b.id, 0) * 1009 + coalesce(0, 0)), 0) as s
    from (select a.id, a.k from ta a left join tc c on c.k = a.k where c.id is null) a left join tb b on a.k = b.k) h
  cross join (select count(*) as c, count(b.id) as m, coalesce(sum(coalesce(a.id, 0) * 1000003 + coalesce(b.id, 0) * 1009 + coalesce(0, 0)), 0) as s
    from (select a.id, a.k from ta a left join tc c on (c.k >= a.k and c.k <= a.k) where c.id is null) a left join tb b on (a.k >= b.k and a.k <= b.k)) n;

-- F18: table LEFT JOIN (outer join), ON references both inner tables
select 'F18 H' as tag, q.c, q.m, q.s
  from (select count(*) as c, count(b.id) as m, coalesce(sum(coalesce(a.id, 0) * 1000003 + coalesce(b.id, 0) * 1009 + coalesce(c.id, 0)), 0) as s
    from ta a left join (tb b left join tc c on c.k = b.k) on a.k = b.k and coalesce(c.w, 9) > a.z) q;
select 'F18' as tag, iif(h.c = n.c and h.m = n.m and h.s = n.s, 'PASS', 'FAIL') as res,
       h.c, h.m, h.s, n.c as nl_c, n.m as nl_m, n.s as nl_s
  from (select count(*) as c, count(b.id) as m, coalesce(sum(coalesce(a.id, 0) * 1000003 + coalesce(b.id, 0) * 1009 + coalesce(c.id, 0)), 0) as s
    from ta a left join (tb b left join tc c on c.k = b.k) on a.k = b.k and coalesce(c.w, 9) > a.z) h
  cross join (select count(*) as c, count(b.id) as m, coalesce(sum(coalesce(a.id, 0) * 1000003 + coalesce(b.id, 0) * 1009 + coalesce(c.id, 0)), 0) as s
    from ta a left join (tb b left join tc c on (c.k >= b.k and c.k <= b.k)) on (a.k >= b.k and a.k <= b.k) and coalesce(c.w, 9) > a.z) n;

-- ===== G: query shapes =====

-- G01: FIRST with ORDER BY over the joined rows
select 'G01 H' as tag, q.c, q.m, q.s
  from (select count(*) as c, count(q.bid) as m, coalesce(sum(coalesce(q.aid, 0) * 1000003 + coalesce(q.bid, 0) * 1009 + coalesce(0, 0)), 0) as s
    from (select first 100 a.id as aid, b.id as bid from ta a left join tb b on a.k = b.k and b.y > a.z * 10 order by a.id, b.id) q) q;
select 'G01' as tag, iif(h.c = n.c and h.m = n.m and h.s = n.s, 'PASS', 'FAIL') as res,
       h.c, h.m, h.s, n.c as nl_c, n.m as nl_m, n.s as nl_s
  from (select count(*) as c, count(q.bid) as m, coalesce(sum(coalesce(q.aid, 0) * 1000003 + coalesce(q.bid, 0) * 1009 + coalesce(0, 0)), 0) as s
    from (select first 100 a.id as aid, b.id as bid from ta a left join tb b on a.k = b.k and b.y > a.z * 10 order by a.id, b.id) q) h
  cross join (select count(*) as c, count(q.bid) as m, coalesce(sum(coalesce(q.aid, 0) * 1000003 + coalesce(q.bid, 0) * 1009 + coalesce(0, 0)), 0) as s
    from (select first 100 a.id as aid, b.id as bid from ta a left join tb b on (a.k >= b.k and a.k <= b.k) and b.y > a.z * 10 order by a.id, b.id) q) n;

-- G02: GROUP BY above the join
select 'G02 H' as tag, q.c, q.m, q.s
  from (select count(*) as c, sum(q.cnt) as m, sum(q.cn * (q.z + 1) + q.cnt * 1000) as s
    from (select a.z, count(b.id) as cnt, count(*) as cn from ta a left join tb b on a.k = b.k and b.y > a.z * 10 group by a.z) q) q;
select 'G02' as tag, iif(h.c = n.c and h.m = n.m and h.s = n.s, 'PASS', 'FAIL') as res,
       h.c, h.m, h.s, n.c as nl_c, n.m as nl_m, n.s as nl_s
  from (select count(*) as c, sum(q.cnt) as m, sum(q.cn * (q.z + 1) + q.cnt * 1000) as s
    from (select a.z, count(b.id) as cnt, count(*) as cn from ta a left join tb b on a.k = b.k and b.y > a.z * 10 group by a.z) q) h
  cross join (select count(*) as c, sum(q.cnt) as m, sum(q.cn * (q.z + 1) + q.cnt * 1000) as s
    from (select a.z, count(b.id) as cnt, count(*) as cn from ta a left join tb b on (a.k >= b.k and a.k <= b.k) and b.y > a.z * 10 group by a.z) q) n;

-- G03: DISTINCT above the join
select 'G03 H' as tag, q.c, q.m, q.s
  from (select count(*) as c, count(q.k2) as m, coalesce(sum(coalesce(q.k, -1) * 100 + coalesce(q.k2, -1)), 0) as s
    from (select distinct a.k, b.k2 from ta a left join tb b on a.k = b.k and b.y > 50) q) q;
select 'G03' as tag, iif(h.c = n.c and h.m = n.m and h.s = n.s, 'PASS', 'FAIL') as res,
       h.c, h.m, h.s, n.c as nl_c, n.m as nl_m, n.s as nl_s
  from (select count(*) as c, count(q.k2) as m, coalesce(sum(coalesce(q.k, -1) * 100 + coalesce(q.k2, -1)), 0) as s
    from (select distinct a.k, b.k2 from ta a left join tb b on a.k = b.k and b.y > 50) q) h
  cross join (select count(*) as c, count(q.k2) as m, coalesce(sum(coalesce(q.k, -1) * 100 + coalesce(q.k2, -1)), 0) as s
    from (select distinct a.k, b.k2 from ta a left join tb b on (a.k >= b.k and a.k <= b.k) and b.y > 50) q) n;

-- G04: UNION ALL of two outer joins
select 'G04 H' as tag, q.c, q.m, q.s
  from (select count(*) as c, count(q.bid) as m, coalesce(sum(coalesce(q.aid, 0) * 1000003 + coalesce(q.bid, 0) * 1009 + coalesce(0, 0)), 0) as s
    from (select a.id as aid, b.id as bid from ta a left join tb b on a.k = b.k where a.z < 5 union all select a.id, b.id from ta a left join tb b on a.k is not distinct from b.k where a.z >= 5) q) q;
select 'G04' as tag, iif(h.c = n.c and h.m = n.m and h.s = n.s, 'PASS', 'FAIL') as res,
       h.c, h.m, h.s, n.c as nl_c, n.m as nl_m, n.s as nl_s
  from (select count(*) as c, count(q.bid) as m, coalesce(sum(coalesce(q.aid, 0) * 1000003 + coalesce(q.bid, 0) * 1009 + coalesce(0, 0)), 0) as s
    from (select a.id as aid, b.id as bid from ta a left join tb b on a.k = b.k where a.z < 5 union all select a.id, b.id from ta a left join tb b on a.k is not distinct from b.k where a.z >= 5) q) h
  cross join (select count(*) as c, count(q.bid) as m, coalesce(sum(coalesce(q.aid, 0) * 1000003 + coalesce(q.bid, 0) * 1009 + coalesce(0, 0)), 0) as s
    from (select a.id as aid, b.id as bid from ta a left join tb b on (a.k >= b.k and a.k <= b.k) where a.z < 5 union all select a.id, b.id from ta a left join tb b on ((a.k >= b.k and a.k <= b.k) or (a.k is null and b.k is null)) where a.z >= 5) q) n;

-- G05: window function above the join
select 'G05 H' as tag, q.c, q.m, q.s
  from (select count(*) as c, count(q.bid) as m, coalesce(sum(coalesce(q.aid, 0) * 1000003 + coalesce(q.bid, 0) * 1009 + coalesce(0, 0)), 0) as s
    from (select a.id as aid, b.id as bid, row_number() over (partition by a.id order by b.id) as rn from ta a left join tb b on a.k = b.k) q where q.rn <= 2) q;
select 'G05' as tag, iif(h.c = n.c and h.m = n.m and h.s = n.s, 'PASS', 'FAIL') as res,
       h.c, h.m, h.s, n.c as nl_c, n.m as nl_m, n.s as nl_s
  from (select count(*) as c, count(q.bid) as m, coalesce(sum(coalesce(q.aid, 0) * 1000003 + coalesce(q.bid, 0) * 1009 + coalesce(0, 0)), 0) as s
    from (select a.id as aid, b.id as bid, row_number() over (partition by a.id order by b.id) as rn from ta a left join tb b on a.k = b.k) q where q.rn <= 2) h
  cross join (select count(*) as c, count(q.bid) as m, coalesce(sum(coalesce(q.aid, 0) * 1000003 + coalesce(q.bid, 0) * 1009 + coalesce(0, 0)), 0) as s
    from (select a.id as aid, b.id as bid, row_number() over (partition by a.id order by b.id) as rn from ta a left join tb b on (a.k >= b.k and a.k <= b.k)) q where q.rn <= 2) n;

-- G06: GROUP BY on an indexed outer column (index navigation of the outer table)
select 'G06 H' as tag, q.c, q.m, q.s
  from (select count(*) as c, sum(q.cnt) as m, sum(q.cn * (coalesce(q.k, 0) + 1) + q.cnt * 1000) as s
    from (select a.k, count(*) as cn, count(c.id) as cnt from tbi a left join tc c on c.k = a.k and c.w > 1 group by a.k) q) q;
select 'G06' as tag, iif(h.c = n.c and h.m = n.m and h.s = n.s, 'PASS', 'FAIL') as res,
       h.c, h.m, h.s, n.c as nl_c, n.m as nl_m, n.s as nl_s
  from (select count(*) as c, sum(q.cnt) as m, sum(q.cn * (coalesce(q.k, 0) + 1) + q.cnt * 1000) as s
    from (select a.k, count(*) as cn, count(c.id) as cnt from tbi a left join tc c on c.k = a.k and c.w > 1 group by a.k) q) h
  cross join (select count(*) as c, sum(q.cnt) as m, sum(q.cn * (coalesce(q.k, 0) + 1) + q.cnt * 1000) as s
    from (select a.k, count(*) as cn, count(c.id) as cnt from tbi a left join tc c on (c.k >= a.k and c.k <= a.k) and c.w > 1 group by a.k) q) n;

-- G07: outer join inside a correlated scalar sub-query of WHERE
select 'G07 H' as tag, q.c, q.m, q.s
  from (select count(*) as c, count(x.k) as m, coalesce(sum(x.id), 0) as s
    from ta x where (select count(b.id) from ta a left join tb b on a.k = b.k and b.y > x.z * 10 where a.z = x.z) > 60) q;
select 'G07' as tag, iif(h.c = n.c and h.m = n.m and h.s = n.s, 'PASS', 'FAIL') as res,
       h.c, h.m, h.s, n.c as nl_c, n.m as nl_m, n.s as nl_s
  from (select count(*) as c, count(x.k) as m, coalesce(sum(x.id), 0) as s
    from ta x where (select count(b.id) from ta a left join tb b on a.k = b.k and b.y > x.z * 10 where a.z = x.z) > 60) h
  cross join (select count(*) as c, count(x.k) as m, coalesce(sum(x.id), 0) as s
    from ta x where (select count(b.id) from ta a left join tb b on (a.k >= b.k and a.k <= b.k) and b.y > x.z * 10 where a.z = x.z) > 60) n;

-- G08: view with an outer join, WHERE over the view columns
select 'G08 H' as tag, q.c, q.m, q.s
  from (select count(*) as c, count(a.bid) as m, coalesce(sum(coalesce(a.aid, 0) * 1000003 + coalesce(a.bid, 0) * 1009 + coalesce(0, 0)), 0) as s
    from v_ab a where a.y > 50 or a.bid is null) q;
select 'G08' as tag, iif(h.c = n.c and h.m = n.m and h.s = n.s, 'PASS', 'FAIL') as res,
       h.c, h.m, h.s, n.c as nl_c, n.m as nl_m, n.s as nl_s
  from (select count(*) as c, count(a.bid) as m, coalesce(sum(coalesce(a.aid, 0) * 1000003 + coalesce(a.bid, 0) * 1009 + coalesce(0, 0)), 0) as s
    from v_ab a where a.y > 50 or a.bid is null) h
  cross join (select count(*) as c, count(a.bid) as m, coalesce(sum(coalesce(a.aid, 0) * 1000003 + coalesce(a.bid, 0) * 1009 + coalesce(0, 0)), 0) as s
    from v_ab_n a where a.y > 50 or a.bid is null) n;

-- G09: recursive CTE, outer join in the recursive member
select 'G09 H' as tag, q.c, q.m, q.s
  from (with recursive r as (select a.id, a.k, 0 as lvl, cast(null as int) as bid from ta a where a.id <= 5 union all select a.id, a.k, r.lvl + 1, b.id from r join (ta a left join tb b on b.k = a.k and b.y > a.z * 10) on a.id = r.id + 5 where r.lvl < 3) select count(*) as c, count(r.bid) as m, coalesce(sum(r.id * 1000003 + coalesce(r.bid, 0) * 1009 + r.lvl), 0) as s
    from r) q;
select 'G09' as tag, iif(h.c = n.c and h.m = n.m and h.s = n.s, 'PASS', 'FAIL') as res,
       h.c, h.m, h.s, n.c as nl_c, n.m as nl_m, n.s as nl_s
  from (with recursive r as (select a.id, a.k, 0 as lvl, cast(null as int) as bid from ta a where a.id <= 5 union all select a.id, a.k, r.lvl + 1, b.id from r join (ta a left join tb b on b.k = a.k and b.y > a.z * 10) on a.id = r.id + 5 where r.lvl < 3) select count(*) as c, count(r.bid) as m, coalesce(sum(r.id * 1000003 + coalesce(r.bid, 0) * 1009 + r.lvl), 0) as s
    from r) h
  cross join (with recursive r as (select a.id, a.k, 0 as lvl, cast(null as int) as bid from ta a where a.id <= 5 union all select a.id, a.k, r.lvl + 1, b.id from r join (ta a left join tb b on (b.k >= a.k and b.k <= a.k) and b.y > a.z * 10) on a.id = r.id + 5 where r.lvl < 3) select count(*) as c, count(r.bid) as m, coalesce(sum(r.id * 1000003 + coalesce(r.bid, 0) * 1009 + r.lvl), 0) as s
    from r) n;

-- G10: IN (sub-query with an outer join)
select 'G10 H' as tag, q.c, q.m, q.s
  from (select count(*) as c, count(x.k) as m, coalesce(sum(x.id), 0) as s
    from tc x where x.k in (select a.k from ta a left join tb b on a.k = b.k and b.y > x.w * 20 where b.id is null)) q;
select 'G10' as tag, iif(h.c = n.c and h.m = n.m and h.s = n.s, 'PASS', 'FAIL') as res,
       h.c, h.m, h.s, n.c as nl_c, n.m as nl_m, n.s as nl_s
  from (select count(*) as c, count(x.k) as m, coalesce(sum(x.id), 0) as s
    from tc x where x.k in (select a.k from ta a left join tb b on a.k = b.k and b.y > x.w * 20 where b.id is null)) h
  cross join (select count(*) as c, count(x.k) as m, coalesce(sum(x.id), 0) as s
    from tc x where x.k in (select a.k from ta a left join tb b on (a.k >= b.k and a.k <= b.k) and b.y > x.w * 20 where b.id is null)) n;

-- G11: PSQL: the join is executed ten times with a different variable
set term ^;
execute block returns (tag varchar(8), res varchar(4), c bigint, m bigint, s bigint,
                       nl_c bigint, nl_m bigint, nl_s bigint) as
declare p int = 0;
declare c1 bigint;
declare m1 bigint;
declare s1 bigint;
begin
  c = 0; m = 0; s = 0; nl_c = 0; nl_m = 0; nl_s = 0;
  while (p < 10) do
  begin
    select count(*), count(b.id), coalesce(sum(a.id * 1000003 + coalesce(b.id, 0) * 1009), 0)
      from ta a left join tb b on a.k = b.k and b.y > :p * 10 and a.z >= :p - 5
      into :c1, :m1, :s1;
    c = c + c1; m = m + m1; s = s + s1 + p;
    select count(*), count(b.id), coalesce(sum(a.id * 1000003 + coalesce(b.id, 0) * 1009), 0)
      from ta a left join tb b on (a.k >= b.k and a.k <= b.k) and b.y > :p * 10 and a.z >= :p - 5
      into :c1, :m1, :s1;
    nl_c = nl_c + c1; nl_m = nl_m + m1; nl_s = nl_s + s1 + p;
    p = p + 1;
  end
  tag = 'G11 H';
  suspend;
  tag = 'G11';
  res = iif(c = nl_c and m = nl_m and s = nl_s, 'PASS', 'FAIL');
  suspend;
end^
set term ;^

set explain off;
select 'END' as tag, count(*) as cases_done from rdb$database;
exit;
